if(REC.mark){ var _rs=Math.floor((Date.now()-REC.t0)/1000), _rt='&#9679; REC '+fmtClock(_rs)+' / '+fmtClock(REC.max); if(REC.mark._t!==_rt){ REC.mark._t=_rt; REC.mark.innerHTML=_rt; } }
